    "breakpoints": {
      "compact": "With AppShell footerPlacement auto (default), attribution flows at the end of main and scrolls away.",
      "medium": "Shell-bottom chrome row outside the main scrollport.",
      "large": "Same shell-bottom chrome as medium."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS; text alignment inherits document direction.",
    "mirroredValues": []
