import type { ReactNode } from 'react'
import './styles.css'

export interface FooterProps {
  /** Credits, legal links, or other attribution content. */
  children?: ReactNode
  className?: string
}

/**
 * First-class AppShell attribution chrome. Mount in AppShell `footer` / `#footer`
 * (not Navigation `#footer` — that is the sidebar account foot).
 */
export function Footer({ children, className }: FooterProps) {
  const classes = ['cu-footer', className].filter(Boolean).join(' ')
  return (
    <div
      className={classes}
      data-ai-role="footer"
      data-ai-intent="show-attribution"
      data-ai-state="default"
    >
      {children}
    </div>
  )
}

/*
 * Footer — AppShell shell-bottom attribution (credits / legal / links).
 * Mount in AppShell footer / #footer. Distinct from Navigation sidebar foot
 * (NavAccountCard / Navigation #footer).
 */
.cu-footer {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--cu-space-1);
  min-inline-size: 0;
  max-inline-size: 100%;
  text-align: center;
  font-size: 0.75rem;
  line-height: 1.4;
  color: inherit;
  /* No default fill — AppShell __footer host is also transparent. */
  background: transparent;
}

.cu-footer a {
  color: inherit;
}
